# Fixes desktop trackpad scrolling regression: scopes the mobile
# touch-drag fix to a mobile-only media query instead of applying it globally.
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\globals.css"), $bytes)
Write-Host "UPDATED: src\app\globals.css" -ForegroundColor Green
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan